import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { Boss } from '../Entity/Boss';
import type { TurretData } from '../Entity/TurretData';
import type { Plane } from '../Entity/Plane';
import { Bullet } from '../Entity/Bullet';

export class TurretSystem implements System {

    onTick(world: World, dt: number): void {
        for (const boss of world.query<Boss>('boss')) {
            if (boss.hp <= 0) continue;
            for (const turret of boss.turrets) {
                this._tickAim(world, boss, turret, dt);
                this._tickFire(world, boss, turret, dt);
            }
        }
    }

    // ===== 瞄准 =====
    private _tickAim(world: World, boss: Boss, turret: TurretData, dt: number): void {
        const c = turret.config;
        switch (c.aimMode) {
            case 'fixed':
                turret.aimAngle = c.baseAngle;
                break;
            case 'target':
                this._aimAtPlayer(world, boss, turret, dt);
                break;
            case 'spin':
                turret.aimAngle = (turret.aimAngle + c.aimSpeed * dt) % 360;
                break;
            case 'oscillate':
                turret.oscPhase += (c.aimSpeed * Math.PI / 180) * dt;
                turret.aimAngle = c.baseAngle
                    + Math.sin(turret.oscPhase) * c.oscRange;
                break;
        }
    }

    private _aimAtPlayer(world: World, boss: Boss, turret: TurretData, dt: number): void {
        const player = this._findPlayer(world);
        if (!player) return;

        const c = turret.config;
        const turretX = boss.x + c.offsetX;
        const turretY = boss.y + c.offsetY;

        const targetAngle = Math.atan2(player.y - turretY, player.x - turretX)
            * 180 / Math.PI;

        // 平滑旋转：diff 归一到 [-180, 180]，每帧最多转 aimSpeed * dt
        let diff = targetAngle - turret.aimAngle;
        diff = ((diff + 180) % 360 + 360) % 360 - 180;

        const maxStep = c.aimSpeed * dt;
        if (Math.abs(diff) <= maxStep) {
            turret.aimAngle = targetAngle;
        } else {
            turret.aimAngle += Math.sign(diff) * maxStep;
        }
    }

    private _findPlayer(world: World): Plane | null {
        for (const p of world.query<Plane>('player')) return p;
        return null;
    }

    // ===== 开火 =====
    private _tickFire(world: World, boss: Boss, turret: TurretData, dt: number): void {
        const c = turret.config;
        turret.cooldownTimer += dt;

        let guard = 0;
        while (turret.cooldownTimer >= c.fireInterval && guard++ < 16) {
            turret.cooldownTimer -= c.fireInterval;
            this._fire(world, boss, turret);
        }
    }

    private _fire(world: World, boss: Boss, turret: TurretData): void {
        const c = turret.config;
        const x = boss.x + c.offsetX;
        const y = boss.y + c.offsetY;

        if (c.spreadCount <= 1 || c.spreadAngle <= 0) {
            this._spawnBullet(world, x, y, turret.aimAngle, c);
            return;
        }

        // 扇形：以 aimAngle 为中心向左右散开
        const step = c.spreadAngle / (c.spreadCount - 1);
        const start = turret.aimAngle - c.spreadAngle / 2;
        for (let i = 0; i < c.spreadCount; i++) {
            this._spawnBullet(world, x, y, start + step * i, c);
        }
    }

    private _spawnBullet(world: World, x: number, y: number, angleDeg: number, c: { bulletSpeed: number; bulletDamage: number; bulletType: string }): void {
        const rad = angleDeg * Math.PI / 180;
        const b = new Bullet();
        b.x = x;
        b.y = y;
        b.dirX = Math.cos(rad);
        b.dirY = Math.sin(rad);
        b.speed = c.bulletSpeed;
        b.damage = c.bulletDamage;
        b.isPlayerBullet = false;
        world.add(b);
    }
}